import React, { useState } from 'react';
import styles from './RegistrationForm.module.css';

const RegistrationForm = () => {
  const [formData, setFormData] = useState({
    firstName: '', email: '', password: '', agreeToTerms: false
  });
  const [errors, setErrors] = useState({});
  const [isSubmitted, setIsSubmitted] = useState(false);

  const handleInputChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (formData.firstName && formData.email) {
      setIsSubmitted(true);
    } else {
      setErrors({ firstName: "Required", email: "Required" });
    }
  };

  if (isSubmitted) return <div className={styles.container}><h3>Registration Successful!</h3></div>;

  return (
    <div className={styles.container}>
      <h1 className={styles.title}>Create Account</h1>
      <form className={styles.form} onSubmit={handleSubmit}>
        <div className={styles.formGroup}>
          <label>First Name *</label>
          <input type="text" name="firstName" className={styles.input} onChange={handleInputChange} />
        </div>
        <div className={styles.formGroup}>
          <label>Email *</label>
          <input type="email" name="email" className={styles.input} onChange={handleInputChange} />
        </div>
        <button type="submit" className={styles.submitButton}>Create Account</button>
      </form>
    </div>
  );
};

export default RegistrationForm;
